addon_table.spoken_places_uk = {
    [1416] = {
        text = [[Над цими вершинами важкі хмари майже не розходяться, і дощ іде частіше, ніж буває сухо. Нижче від засніжених вершин схили вкриті лісом. Біля підніжжя гір люди й вищі ельфи розгромили імперію Амані в останній битві Трольських воєн.

Колись тут стояли дві могутні держави. Альтерак був містом-державою серед гір, що згодом підкорила чималу частину північних земель. Даларан, місто Кірін-Тору, стояв біля Лордамерського озера. Альтерак упав за зраду під час Другої війни. Даларан зруйнували в Третій війні. Тепер, поки триває відбудова, його чарівники відкрили купол, яким накрили місто.

Руїни Альтерака тримають оґри Скелелами. Синдикат, збіговисько розбійників, яке зібрав принц занепалого королівського дому Аліден Перенольд, утримує Странбрад і навколишні угіддя. За решту земель точаться сутички. Глибоко в горах орки Морозних Вовків і дворфи з Варти Грозової Вершини змагаються за окрему долину.]],
    },
    [1417] = {
        text = [[У цьому сухому й кам’янистому краї король Торадін звів Стром, столицю Аратора. Неподалік він збудував велику стіну, щоб захистити свій народ від тролів Амані. Коли імперія впала, імператорська варта, що лишилася там, заснувала Стромварт у старому місті. Стіна Торадіна й досі тягнеться північним краєм височини, подекуди обвалена й з широкими проломами.

Стромварт оминув чуму Скари, але впав під натиском Синдикату й брилоруких оґрів. Рештки його війська відступили до невеликої ущелини на півночі, яку тепер називають Опорним пунктом. Людських захисників очолює принц Ґален Тролебій. Вони й досі б’ються за зруйноване місто із Синдикатом та оґрами.

На сході Орда утримує Молотобій. Це колишній табір полонених орків, який вона захопила й перейменувала на честь полеглого воєвождя Орґріма Молота Згуби.]],
    },
    [1420] = {
        text = [[Над Тірісфальським переліссям нависає похмуре зелене небо. Ці лісисті пагорби на північному узбережжі Лордерона просякла проклята чума Короля-Ліча. Дерева й чагарники тримаються за останні крихти життя.

За короля Теренаса тут були мирні господарства й містечка, де поколіннями щасливо жили родини. Перелісся впало одним із перших, коли принц Артас Менетіл плюндрував Лордерон. Люди помирали й повставали рабами Скари. Для решти викопували братські могили. Згодом леді Сильвана Вітрогін і її вільні Відречені зробили ці землі своїми.

У Відречених тут є вороги. Багряний Похід утримує кілька опорних пунктів, серед них Багряний монастир — твердиню своєї віри. Поплічники Скари досі оскверняють занедбані хутори й млини. У західних пагорбах паладини Відречених із Варти Тіра утримують фортецю Бандаріон і зберігають відданість Світлу.]],
    },
    [1421] = {
        text = [[Над трав’янистими пагорбами височать високі сосни зі сріблястою корою. До Третьої війни Альянс беріг цей праліс зеленим і неушкодженим. Потім сюди прийшла Скара, спалила врожай і перебила людей. Після падіння Лордерона доглядати за лісом не було кому. Дерева зблідли й захворіли, поміж ними повис примарний туман. Тепер у лісі тихо, лише часом долинає виття. По всьому краю розкидані занепалі хутори й покинуті копальні, де оселилися темні лісові створіння.

Відречені утримують північ і ведуть невпинну партизанську війну з гнилошкурими ґнолами. Їхнє право на ці землі оспорюють чарівники Даларана й агенти Скари, які зайняли частину спустошених полів. На півдні ще тримається кілька людських поселень. Їх захищають чарівники, надіслані з Даларана також для вивчення чуми й ворґенського прокляття. На південному заході під місяцем мешканці села Поховальні Вогнища перетворюються на ворґенів. Їх прокляв верховний маг Аруґал, який не полишає темних веж фортеці Тіньового Ікла.]],
    },
    [1422] = {
        text = [[До чуми на схід від столиці Лордерона були ліси й сільські угіддя. Вогнеділ був осідком крайової влади, а до Андорала звозили зерно з північних провінцій і розподіляли його по всьому королівству.

Кел’Тузад і Культ Проклятих знали, що через зерно чума пошириться найшвидше. Вони заразили його й поставили по велетенському казану на полях чотирьох найбільших господарств. Коли Лордерон упав, ліси почали гинути. Із сосен осипається хвора бура глиця, а на їхніх стовбурах набухають нарости, мов пухлини. Над землею висить димчаста сіра імла.

Здається, сам край і досі чинить опір з усіх сил, які в нього лишилися. Багряний Похід тримає Вогнеділ і звідти завдає ударів по Скарі. Єдине мирне місце тут — гробниця Утера, пам’ятник Утерові Світлоносцю.]],
    },
    [1423] = {
        text = [[До чуми тут були господарства й невеликі села. Усі вони тягнулися до Стратгольма, найбільшого міста Лордерона. Принц Артас Менетіл прибув до Стратгольма в пошуках джерела чуми й влаштував у місті очищення. Звідти він вирушив на північ, повернувся одним із лицарів смерті Короля-Ліча й убив власного батька, поклавши край королівству Лордерон.

Тепер тут панує Скара. Стратгольм — її південна столиця, якою править ліч Кел’Тузад. Багряний Похід утримує західні квартали, марно продовжує боротьбу й не пускає туди чужинців. Земля бура й хвора, дерева розпухли й стали схожими на велетенські гриби, а в повітрі висить помаранчева імла. Дорогами нишпорять некроманти й культисти Проклятих. З півночі нападають лісові тролі Амані. Лише біля Каплиці Надії Світла, в невеликому таборі Сріблястого Світанку, радо приймають кожного, хто готовий битися.]],
    },
    [1424] = {
        text = [[Скара спотворила більшу частину Лордерона, але передгір’я Гіллзбраду досі виглядає так, як за часів королівства. Пагорби зелені, луки родючі, земля багата. Серед ланів де-не-де ростуть сосни, а дороги через пасовища з’єднують містечка. З озера Дарроумер на південь витікає річка.

І все ж це найкривавіше поле бою Азероту. Саме тут у Другій війні зійшлися в першій битві Альянс і Орда. Орочі рейдери нападали на прибережні містечка, а лісові тролі билися пліч-о-пліч з ними проти людей і вищих ельфів, які боронили узбережжя. Під час Третьої війни Тралл зібрав орочі клани, вночі пробрався до Південнобережжя й викрав кораблі, щоб перевезти нову Орду за море, до Калімдору.

Скара знищила Тарренський Млин. Відречені зробили містечко своїм найпівденнішим опорним пунктом і тепер тіснять людей Південнобережжя й полів Гіллзбраду, які стоять за Альянс. Обом сторонам дошкуляють розбійники Синдикату, мурлоки й наґи.]],
        areas = {
            ["azurelode mine"] = [[У Лазуровій копальні видобувають залізо для зброярень Альянсу. Шахтарі з полів Гіллзбраду працюють під наглядом десятника Бондса, а вартові стережуть їх. Копальня лежить на південному заході передгір’я, на південь від полів.]],
            ["chillwind point"] = [[З Чумних земель униз ущелиною дме холодний вітер. Саме він дав назву проліску Студовій. Колись цей перевал належав королівству Лордерон. На вершині пагорба стоять давні трольські руїни, де оселився самітник Бат’рах Вітрогляд, шаман із племені тропічних тролів і вправний зброяр.]],
            ["corrahns dagger"] = [[Височину Коррана тримають розбійники Синдикату. Це людські злочинці, якими керує знать занепалого королівства Альтерак. Вони ворогують як з Альянсом, так і з Ордою.]],
            ["crushridge hold"] = [[Біля руїн Альтерака, у печері під земляним пагорбом, оселилося чимало оґрів Скелеламів. Інші розбили табір довкола. У Другій війні королівство Альтерак уклало угоду з Ордою, і за цю зраду решта людських королівств ударила по його столиці. Більшість мешканців утекла. Тепер порожні руїни належать оґрам.]],
            ["darrow hill"] = [[Пагорб Дарроу лежить у північній частині передгір’я Гіллзбраду, під Верхів’ям. Відкритими полями блукають гірські леви й олені. У печерах передгір’я, серед жил альтерацького граніту, облаштували лігво єті.]],
            ["dun garok"] = [[Цю фортецю в південно-східних пагорбах утримують дворфи під проводом капітана Залізопагорба. Вони захищають людей Гіллзбраду й наглядають за Лазуровою копальнею. Відречені не терплять такого сусідства й прагнуть їх знищити.]],
            ["durnholde keep"] = [[У Другій війні сам Орґрім Молот Згуби напав на фортецю Дарнгольд, щоб визволити з її підземель трольського воєводу Зул’джина. Згодом фортеця стала центром управління таборами для полонених орків. Ними керував генерал-лейтенант Еделас Блекмур, самозакоханий п’яниця. Він знайшов ороче немовля біля тіл його вбитих батьків, назвав хлопця Траллом і виростив тут рабом і гладіатором.

Тралл утік, визволив орків із таборів, а тоді повернувся й узяв Дарнгольд в облогу. Він убив Блекмура в поєдинку й покликав дух землі, щоб зрівняти фортецю із землею.

Нині на схід від Тарренського Млина лежать її руїни. Колись у фортеці були казарми, вежа мага й арена. Тепер це опорний пункт Синдикату в передгір’ї. Звідси розбійники вирушають красти коней і вантажі з Південнобережжя.]],
            ["eastern strand"] = [[Східне узбережжя тягнеться вздовж південно-східного берега передгір’я Гіллзбраду. Західне лежить далі тим самим берегом. Ця піщана смуга належить наґам Клинкоспинів, які тримають пляжі й прилегле мілководдя.]],
            ["gallows corner"] = [[На перехресті Негідників в Альтерацьких горах, де сходяться дороги неподалік руїн Альтерака, стоїть порожня напівзруйнована дозорна вежа. Перехрестям заволоділи оґри Скелелами. Вони бродять поміж камінням довкола решток вежі, і більше тут нікого не видно.]],
            ["gavins naze"] = [[Височиною Ґевіна блукають гірські леви. Серед них іноді можна зустріти рідкісну левицю Араґу.

Дворфи з Варти Грозової Вершини стережуть тунель до Альтерацької долини, де їхній клан б’ється з орками Морозних Вовків. Разом з ними на варті стоїть сержант Дурґен Бурешпиль. Доброго слова про Морозних Вовків від нього не почуєш.]],
            ["growless cave"] = [[У глибині Охлялої печери в Альтерацьких горах горить Полум’я Узела, давнє обрядове вогнище. Довкола нього знайшли прихисток гірські єті, а біля входу часто можна зустріти єті на ім’я Зревун.]],
            ["headland"] = [[На схилі урвища Верхів’я відпочиває гірська левиця з невеликою гривою та смугастим хвостом. Це Араґа. Іншої такої кішки в цих пагорбах немає.

Дворфи з Варти Грозової Вершини тримають тут пост неподалік дороги до Альтерацької долини, де їхній клан веде відкриту війну з орками Морозних Вовків. Лейтенант Гаґґердін набирає новобранців до Варти.]],
            ["hillsbrad fields"] = [[Поля Гіллзбраду вкриті яблуневими садами й гарбузовими грядками, поміж якими пасеться худоба. Їхній урожай годує все передгір’я. У Другій війні Орґрім Молот Згуби наказав знищити містечко, щоб залякати інші людські королівства. Звістка швидко розійшлася. Після війни містечко відбудували.

Гіллзбрад і Південнобережжя — єдині землі колишнього Лордерона, яких Третя війна не спустошила вщент. Жодне з містечок не приєдналося до Багряного Походу, а їхні вартові й досі носять гербові накидки Лордерона. Війт Шкваростін керує з ратуші. Йому допомагають рада Гіллзбраду й писар Горрас Білогрив.

Відречені з Тарренського Млина на чолі з верховною карателькою Дарталією загрожують господарствам. Селяни влаштовують засідки. Зброю їм дають коваль Веррінґтан і його учні.]],
            ["misty shore"] = [[Туманне узбережжя тягнеться вздовж Лордамерського озера, між садибою Дандреда й Далараном. На мілководді неквапно рухаються черепахи.

Цей берег утримують двоє людей, союзники Багряного Походу. Вони нападають на кожного, хто підходить надто близько.

По той бік озера видно Світанкові острови, а вдалині — моторошну фортецю Фенріса.]],
            ["nethander stead"] = [[Маєток Нетандера лежить одразу на схід від Південнобережжя. Його покинуті поля заполонили брудноморді ґноли. Це єдине місце, де можна зустріти їхнє плем’я. Тут самі собою ростуть велетенські білі гриби, відомі як брудномордий цвіт.]],
            ["purgation isle"] = [[На південь від берегів Гіллзбраду з води здіймається висока спіральна скеля. На її вершині — цвинтар і руїни дозорної вежі. До Першої війни острів Позбавлення належав Кул-Тірасу.

Тут блукають десятки приречених духів людей і дворфів: паладини, жерці, ченці й маги, які досі не можуть знайти спокою.]],
            ["ravenholdt manor"] = [[Лорд Джорах Воронгольдт керує своєю Лігою вбивць із цього прихованого маєтку Рейвенхольдт в Альтерацьких горах. Вузька стежка піднімається сюди з плоскогір’я й петляє серед гір та крізь невелику печеру. До Ліги приймають лише винятково вправних. Чужинець, який пішов звідси без ножа в спині чи отрути в крові, може вважати, що йому пощастило.

Ліга роками воює із Синдикатом. Її агенти викрадають емблеми синдикатівців: із тим, хто загубить свою, розправляються його ж товариші.]],
            ["slaughter hollow"] = [[Оґри Скелелами живуть у кітлині Убивць, в оґрському кургані в глибині Альтерацьких гір.

У клітці вони тримають полоненого гнома Різза Незатяга. Він благає кожного перехожого не дати оґрам його з’їсти й торгує інженерними припасами крізь ґрати.]],
            ["soferas naze"] = [[Мис Софери над Гіллзбрадом тримає Синдикат. Тут отаборилися його грабіжники й злодії. Дехто з них уже дістався до темного пива з Південнобережжя.]],
            ["southpoint tower"] = [[Смертоловка Леш із Відречених стереже напівзруйновану Південну вежу на західному краю передгір’я Гіллзбраду, трохи південніше від дороги до Срібнохвойного пралісу. Звідти вона стежить за діями Альянсу в околицях.]],
            ["southshore"] = [[Південнобережжя було звичайним рибальським селом, коли сюди прибули тисячі човнів. Вони привезли вцілілих мешканців Штормовію, чиє королівство Орда знищила в Першій війні. Утікачі оселилися поруч із селом й присягнули новому Альянсові. У Другій війні містечко стало жвавим військовим портом. Орда прагнула заволодіти нафтою, на яку були багаті тутешні води. Зрештою вона захопила порт, і Орґрім Молот Згуби поставив свій флот на якір у гавані. По війні Альянс відбудував Південнобережжя.

На початку Третьої війни орки Тралла вночі прокралися до містечка й викрали кораблі, щоб попливти до Калімдору.

Тепер Південнобережжя — тихий порт, одне з небагатьох місць у Лордероні, де люди досі вірні Альянсу. Тут оселилися вцілілі після Третьої війни. Дехто з них колись був лицарем Срібної Десниці або магом Кірін-Тору. Вулицями ходять вартові, а трохи на північ живуть Відречені з Тарренського Млина.]],
            ["strahnbrad"] = [[Странбрад стоїть у північно-східних передгір’ях Альтерацьких гір. Це місто-привид із покинутою ратушею та кузнею. Колись воно належало королівству Альтерак, а після Другої війни відійшло до Лордерона.

Незадовго до Третьої війни орки Чорної Скелі напали на місто, щоб захопити рабів для жертвопринесення Палаючому Легіону. Странбрад боронила лише жменька піхотинців, та звістка все ж дійшла до лицарів Срібної Десниці. Утер Світлоносець вирушив до орочого табору, а принц Артас Менетіл поспішив боронити місто. Коли Артас прибув, напад уже тривав. Багато мешканців загинуло, але принц і вцілілі захисники розгромили орків та вбили їхнього ватажка, Рабовласника.

Тепер Странбрад — головна база Синдикату.]],
            ["tarren mill"] = [[На початку Другої війни лучники вищих ельфів зі Срібномісяця вирушили на південь, щоб оцінити загрозу від орків. На луках біля Тарренського Млина вони потрапили в засідку. Їх доправили до сусіднього табору полонених. Король Теренас послав воїнів Альянсу, і ті визволили бранців. Після цього рада Срібномісяця надала війська Квел’Таласа в розпорядження Альянсу Лордерона.

Нині містечко утримують Відречені. Церква, кілька будинків і всохлі сади занепали. Звідси Відречені воюють із містечками Альянсу — Південнобережжям і Дун-Ґароком. Землі між Тарренським Млином і Південнобережжям сумнозвісні через безперервні бої.]],
            ["thoradins wall"] = [[Невдовзі після заснування Аратора, коли його столицею став Стром, король Торадін наказав звести велику стіну, щоб захистити людство від тролів Амані. Вона тягнеться між передгір’ям Гіллзбраду та височиною Араті.

За багато століть стіну Торадіна тяжко пошкоджено. Від неї лишилися руїни.]],
            ["western strand"] = [[Західне узбережжя лежить на південно-західному березі передгір’я Гіллзбраду. Мурлоки Розірваного Плавника розбили вздовж берега невеликі табори, а Енді Мурґол патрулює околиці.]],
        },
    },
    [1425] = {
        text = [[Захід Внутрішніх земель тримають дворфи Дикого Молота. Тут вони приручають диких грифонів. Зв’язок між ними став таким міцним, що дворфи звели у своєму місті велетенський пам’ятник у подобі грифона. Лісові тролі, які володіли цим краєм раніше й лишилися тут після падіння імперії Амані, вважають, що дворфи захопили землі їхніх предків. Вони нападають на грифонячі гніздів’я.

Дворфи Дикого Молота майже нічого не знали про Орду, коли під час Другої війни орки ввійшли у Внутрішні землі. Вершники на грифонах під проводом тана Курдрана Дикого Молота зустріли загарбників із неба, жбурляючи в їхні колони заряджені грозою молоти й не даючи їм перепочинку. Воєвождь Орґрім Молот Згуби хотів цим нападом відтягти Альянс, поки сам ударить по Квел’Таласу. Андуїн Лотар розгадав задум, послав половину війська до ельфів, а сам бився поруч із Курдраном. Разом вони вигнали орків і їхніх союзників, лісових тролів. Курдран присягнув від імені свого королівства на вірність Альянсу.

Із трьох тутешніх трольських племен лише Сколотий Бивень став на бік Орди.]],
    },
}
